INSERT INTO `book` VALUES (30,'Harry Potter and the Sorcerer\'s Stone',26,'978-0590353427',1997,'Fiction','The first novel in the Harry Potter series following Harry Potter, a young wizard who discovers his magical heritage.','Borrowed','https://i.imgur.com/eOztqQv.jpeg'),(31,'The Firm',27,'978-0385415805',1991,'Fiction','A legal thriller about a young lawyer who joins a firm that is not what it appears to be.','Available','https://i.imgur.com/D3UYeWR.jpeg'),(32,'Angels & Demons',28,'978-0671027360',2000,'Fiction','A mystery-thriller novel following Robert Langdon as he tries to stop a terrorist organization from destroying Vatican City.','Available','https://i.imgur.com/1u9tXw1.jpeg'),(33,'Norwegian Wood',29,'978-0375704024',1987,'Fiction','A nostalgic story of loss and burgeoning sexuality set in Tokyo during the late 1960s.','Borrowed','https://i.imgur.com/m0lijq7.jpeg'),(35,'The Casual Vacancy',26,'978-0316228534',2012,'Fiction','A novel about a parish council election in the small English town of Pagford.','Available','https://i.imgur.com/7i0TsNE.jpeg'),(36,'The Pelican Brief',27,'978-0385418233',1992,'Fiction','A legal thriller about a law student who uncovers a conspiracy while investigating the assassinations of two Supreme Court justices.','Available','https://i.imgur.com/kFLBfhu.jpeg'),(37,'The Da Vinci Code',28,'978-0307474278',2003,'Fiction','A mystery thriller novel that follows symbologist Robert Langdon as he investigates a murder in Paris\' Louvre Museum.','Available','https://i.imgur.com/xc6EoHN.jpeg'),(38,'Foundation',30,'978-0553293357',1951,'Sci-Fi','The first novel in Isaac Asimov\'s Foundation series, depicting the fall of a vast interstellar empire and the attempt to shorten the ensuing dark age.','Available','https://i.imgur.com/y6ZiOs1.jpeg'),(39,'I, Robot',30,'978-0553294385',1950,'Sci-Fi','A collection of nine science fiction short stories by Isaac Asimov, examining the interaction of humans and robots.','Available','https://i.imgur.com/Tufa3tj.jpeg'),(40,'2001: A Space Odyssey',31,'978-0451457998',1968,'Sci-Fi','A science fiction novel about a voyage to Jupiter with the sentient computer HAL after the discovery of a mysterious monolith.','Borrowed','https://i.imgur.com/baiy9f2.jpeg'),(41,'Do Androids Dream of Electric Sheep?',32,'978-0345404473',1968,'Sci-Fi','A post-apocalyptic science fiction novel set in a future Earth following World War Terminus.','Available','https://i.imgur.com/kWuKFza.jpeg'),(42,'The Left Hand of Darkness',33,'978-0441478125',1969,'Sci-Fi','A science fiction novel set in the fictional Hainish universe, dealing with themes of gender and sexuality on a planet where inhabitants can change gender.','Available','https://i.imgur.com/k4th35e.jpeg'),(43,'Dune',34,'978-0441172719',1965,'Sci-Fi','A science fiction novel set in the distant future amidst a feudal interstellar society.','Borrowed','https://i.imgur.com/YA15fI0.jpeg'),(44,'The Gods Themselves',30,'978-0553288100',1972,'Sci-Fi','A science fiction novel dealing with themes of alien sexuality and parallel universes.','Available','https://i.imgur.com/pRmlaIQ.jpeg'),(45,'Rendezvous with Rama',31,'978-0553287899',1973,'Sci-Fi','A science fiction novel about a mysterious alien spacecraft that enters the Solar System.','Available','https://i.imgur.com/HUP5yuI.jpeg'),(46,'Ubik',32,'978-0547572298',1969,'Sci-Fi','A science fiction novel by Philip K. Dick set in a future where psychic powers are common.','Available','https://i.imgur.com/DHoX5h9.jpeg'),(47,'The Dispossessed',33,'978-0060512750',1974,'Sci-Fi','An anarchist utopian science fiction novel set in the fictional Hainish universe.','Available','https://i.imgur.com/eVtZxeO.jpeg'),(48,'The Hobbit',35,'978-0618260300',1937,'Fantasy','A fantasy novel about the adventures of hobbit Bilbo Baggins in Middle-earth.','Available','https://i.imgur.com/dPLqBy6.jpeg'),(49,'The Fellowship of the Ring',35,'978-0618346257',1954,'Fantasy','The first volume of The Lord of the Rings, following the journey of Frodo Baggins to destroy the One Ring.','Available','https://i.imgur.com/ICgGaUY.jpeg'),(50,'A Game of Thrones',36,'978-0553103540',1996,'Fantasy','The first novel in A Song of Ice and Fire series, set in the fictional continents of Westeros and Essos.','Available','https://i.imgur.com/I4HTvYL.jpeg'),(51,'Good Omens',37,'978-0060853983',1990,'Fantasy','A comedy about the birth of the son of Satan and the coming of the End Times.','Available','https://i.imgur.com/gKm39cr.jpeg'),(52,'The Way of Kings',38,'978-0765326355',2010,'Fantasy','The first book in The Stormlight Archive series, set on the world of Roshar.','Available','https://i.imgur.com/vjDR2Sv.jpeg'),(53,'The Name of the Wind',39,'978-0756404741',2007,'Fantasy','The first book in The Kingkiller Chronicle, following the life of Kvothe, a legendary musician and adventurer.','Available','https://i.imgur.com/41UGqYy.jpeg'),(54,'The Two Towers',35,'978-0618346264',1954,'Fantasy','The second volume of The Lord of the Rings, continuing the journey to destroy the One Ring.','Available','https://i.imgur.com/RB5v0aN.jpeg'),(55,'A Clash of Kings',36,'978-0553108033',1998,'Fantasy','The second novel in A Song of Ice and Fire, continuing the War of the Five Kings.','Available','https://i.imgur.com/a2WtiSc.jpeg'),(56,'Mort',37,'978-0061020681',1987,'Fantasy','A Discworld novel about Death taking on an apprentice.','Available','https://i.imgur.com/FKOZZRi.jpeg'),(57,'Words of Radiance',38,'978-0765326362',2014,'Fantasy','The second book in The Stormlight Archive, continuing the story on Roshar.','Available','https://i.imgur.com/ocfhVbB.jpeg'),(58,'Murder on the Orient Express',40,'978-0062693662',1934,'Mystery','A detective novel in which Hercule Poirot investigates a murder on the luxurious Orient Express train.','Available','https://i.imgur.com/FxL8ndK.jpeg'),(59,'And Then There Were None',40,'978-0312330873',1939,'Mystery','A mystery novel about ten people who are invited to an isolated island and are killed one by one.','Available','https://i.imgur.com/X0xwV4l.jpeg'),(60,'The Hound of the Baskervilles',41,'978-0199536965',1902,'Mystery','A detective novel featuring Sherlock Holmes investigating the death of Sir Charles Baskerville.','Available','https://i.imgur.com/MTG01Do.jpeg'),(61,'Gone Girl',42,'978-0307588371',2012,'Mystery','A psychological thriller about the disappearance of a woman on her fifth wedding anniversary.','Available','https://i.imgur.com/9cBQDgK.jpeg'),(62,'The Girl with the Dragon Tattoo',43,'978-0307454546',2005,'Mystery','A psychological thriller novel about a journalist and a hacker investigating a wealthy family.','Available','https://i.imgur.com/qzlOWbm.jpeg'),(63,'Along Came a Spider',44,'978-0446692636',1993,'Mystery','The first novel in the Alex Cross series about a detective hunting a serial killer.','Available','https://i.imgur.com/EsrrzdU.jpeg'),(64,'The ABC Murders',40,'978-0062073563',1936,'Mystery','A detective novel in which Hercule Poirot investigates a series of murders committed in alphabetical order.','Available','https://i.imgur.com/wytD1Od.jpeg'),(65,'The Adventures of Sherlock Holmes',41,'978-0199536958',1892,'Mystery','A collection of twelve short stories featuring Sherlock Holmes and Dr. Watson.','Available','https://i.imgur.com/mAkuKh8.jpeg'),(66,'Vision in White',45,'978-0425228293',2009,'Romance','The first book in the Bride Quartet series about four friends who run a wedding planning business.','Available','https://i.imgur.com/gpEajCu.jpeg'),(67,'The Notebook',46,'978-0446605239',1996,'Romance','A romantic novel about a poor young man who falls in love with a rich young woman.','Available','https://i.imgur.com/xaxfUVe.jpeg'),(68,'Pride and Prejudice',47,'978-0141439518',1813,'Romance','A romantic novel of manners that follows the emotional development of Elizabeth Bennet.','Available','https://i.imgur.com/duUQjQk.jpeg'),(69,'The Promise',48,'978-0440241906',1978,'Romance','A romance novel about a young woman who falls in love with a doctor.','Available','https://i.imgur.com/89QkSTF.jpeg'),(70,'The Duke and I',49,'978-0380800827',2000,'Romance','The first novel in the Bridgerton series about the romantic adventures of the Bridgerton family.','Available','https://i.imgur.com/Wht5WIF.jpeg'),(71,'It Ends with Us',46,'978-1501110368',2016,'Romance','A romance novel about a woman who falls in love with a neurosurgeon.','Available','https://i.imgur.com/SF9nNw9.jpeg'),(72,'Message in a Bottle',46,'978-0446672216',1998,'Romance','A romance novel about a woman who finds a love letter in a bottle.','Available','https://i.imgur.com/W2J3Ggo.jpeg'),(73,'Sense and Sensibility',47,'978-0141439662',1811,'Romance','A novel about the Dashwood sisters, Elinor and Marianne, as they come of age.','Available','https://i.imgur.com/n4DvdiS.jpeg'),(74,'The Call of Cthulhu',50,'978-1512390664',1928,'Horror','A short story about the Cthulhu Mythos, describing a monstrous creature that lies dormant beneath the sea.','Available','https://i.imgur.com/ecp8lKP.jpeg'),(75,'Interview with the Vampire',51,'978-0345476876',1976,'Horror','A gothic horror and vampire novel about a vampire named Louis de Pointe du Lac.','Available','https://i.imgur.com/hliO4pl.jpeg'),(76,'Books of Blood',52,'978-0425074111',1984,'Horror','A collection of horror short stories by Clive Barker.','Available','https://i.imgur.com/cFI7TgC.jpeg'),(77,'The Haunting of Hill House',53,'978-0143134770',1959,'Horror','A Gothic horror novel about four people who stay in a haunted house for a supernatural study.','Available','https://i.imgur.com/Nm0Zn4e.jpeg'),(78,'Dracula',54,'978-0486411095',1897,'Horror','An epistolary Gothic horror novel about Count Dracula\'s attempt to move from Transylvania to England.','Available','https://i.imgur.com/8Wn90D1.jpeg'),(79,'The Exorcist',54,'978-0061007224',1971,'Horror','A horror novel about the demonic possession of a young girl and her mother\'s attempt to rescue her through an exorcism.','Available','https://i.imgur.com/WQ7dI6o.jpeg'),(81,'The Silence of the Lambs',54,'978-0312924584',1988,'Horror','A psychological horror novel about an FBI trainee who seeks the advice of an imprisoned serial killer.','Available','https://i.imgur.com/LXXAlKH.jpeg'),(82,'Steve Jobs',55,'978-1451648539',2011,'Biography','A biography of Apple co-founder Steve Jobs based on more than forty interviews with Jobs.','Available','https://i.imgur.com/2i0e6Hv.jpeg'),(83,'Alexander Hamilton',56,'978-0143034759',2004,'Biography','A biography of American Founding Father Alexander Hamilton.','Available','https://i.imgur.com/sIsGR5l.jpeg'),(84,'John Adams',57,'978-0743223133',2001,'Biography','A biography of John Adams, the second President of the United States.','Available','https://i.imgur.com/yBYdcK3.jpeg'),(85,'Team of Rivals',58,'978-0743270755',2005,'Biography','A biography of Abraham Lincoln focusing on his presidency and his cabinet.','Available','https://i.imgur.com/owNL2ee.jpeg'),(86,'Thomas Jefferson: The Art of Power',59,'978-0812979480',2012,'Biography','A biography of Thomas Jefferson focusing on his political career.','Available','https://i.imgur.com/JrDIw3W.jpeg'),(87,'Einstein: His Life and Universe',55,'978-0743264730',2007,'Biography','A biography of Albert Einstein exploring his scientific achievements and personal life.','Available','https://i.imgur.com/3be5tj8.jpeg'),(88,'Churchill: Walking with Destiny',59,'978-0812997170',2018,'Biography','A biography of Winston Churchill focusing on his leadership during World War II.','Available','https://i.imgur.com/1gFUTbW.jpeg'),(89,'Benjamin Franklin: An American Life',55,'978-0743258074',2003,'Biography','A biography of Benjamin Franklin exploring his life as a scientist, inventor, and statesman.','Available','https://i.imgur.com/eFQn5Bx.jpeg'),(90,'A People\'s History of the United States',60,'978-0062397348',1980,'History','A history of the United States told from the perspective of marginalized groups.','Available','https://i.imgur.com/Gdpxulc.jpeg'),(91,'The Guns of August',61,'978-0345476098',1962,'History','A history of the first month of World War I.','Available','https://i.imgur.com/mxwwv7R.jpeg'),(92,'Band of Brothers',62,'978-0743224543',1992,'History','A history of Easy Company, 506th Parachute Infantry Regiment, 101st Airborne Division during World War II.','Available','https://i.imgur.com/7mTOJZb.jpeg'),(93,'The Devil in the White City',63,'978-0375725609',2003,'History','A historical non-fiction book about the 1893 World\'s Columbian Exposition in Chicago.','Available','https://i.imgur.com/5DuEgmg.jpeg'),(94,'Citizens: A Chronicle of the French Revolution',64,'978-0679726104',1989,'History','A history of the French Revolution from its beginnings to the rise of Napoleon.','Available','https://i.imgur.com/VYVYjhU.jpeg'),(95,'1776',57,'978-0743226714',2005,'History','A history of the American Revolution focusing on the year 1776.','Available','https://i.imgur.com/B56w1bc.jpeg'),(96,'The Wright Brothers',57,'978-1476728742',2015,'History','A biography of the Wright brothers and their invention of the airplane.','Available','https://i.imgur.com/oPQ4RLW.jpeg'),(97,'The Cold War: A New History',64,'978-0143038276',2005,'History','A history of the Cold War from its origins to its end.','Available','https://i.imgur.com/udASK7o.jpeg'),(98,'I Know Why the Caged Bird Sings',65,'978-0345514400',1969,'Poetry','A collection of poems by Maya Angelou exploring themes of identity, racism, and resilience.','Available','https://i.imgur.com/9QP1Mx9.jpeg'),(99,'The Road Not Taken',66,'978-0805069830',1916,'Poetry','A collection of poems by Robert Frost including the famous title poem.','Available','https://i.imgur.com/2ZdZ5yf.jpeg'),(100,'The Complete Poems of Emily Dickinson',67,'978-0316184137',1955,'Poetry','A complete collection of Emily Dickinson\'s poems.','Available','https://i.imgur.com/EyVLOou.jpeg'),(101,'The Collected Poems of Langston Hughes',68,'978-0679764083',1994,'Poetry','A collection of poems by Langston Hughes exploring African American life.','Available','https://i.imgur.com/aJXv6Sq.jpeg'),(102,'Twenty Love Poems and a Song of Despair',69,'978-0143039969',1924,'Poetry','A collection of love poems by Pablo Neruda.','Available','https://i.imgur.com/CgblnnM.jpeg'),(103,'The Waste Land',66,'978-0156948772',1922,'Poetry','A long poem by T.S. Eliot considered one of the most important poems of the 20th century.','Available','https://i.imgur.com/qI5j01p.jpeg'),(104,'Leaves of Grass',68,'978-0451529732',1855,'Poetry','A collection of poems by Walt Whitman celebrating nature, democracy, and the individual.','Available','https://i.imgur.com/7qEBth3.jpeg'),(106,'The Cat in the Hat',70,'978-0394800011',1957,'Children','A children\'s book about a cat who visits two children on a rainy day.','Available','https://i.imgur.com/lb0hHwA.jpeg'),(107,'Charlie and the Chocolate Factory',71,'978-0142410318',1964,'Children','A children\'s novel about a poor boy who wins a tour of a chocolate factory.','Available','https://i.imgur.com/T3YRsqM.jpeg'),(108,'The Tale of Peter Rabbit',72,'978-0723247708',1902,'Children','A children\'s book about a mischievous rabbit who disobeys his mother.','Available','https://i.imgur.com/B8e9wJk.jpeg'),(109,'Where the Wild Things Are',73,'978-0060254926',1963,'Children','A children\'s picture book about a boy named Max who travels to a land of wild creatures.','Available','https://i.imgur.com/8eFS9h3.jpeg'),(110,'Alice\'s Adventures in Wonderland',74,'978-1503222687',1865,'Children','A children\'s novel about a girl who falls down a rabbit hole into a fantasy world.','Available','https://i.imgur.com/aufskiX.jpeg'),(111,'Green Eggs and Ham',70,'978-0394800165',1960,'Children','A children\'s book about Sam-I-am trying to convince someone to try green eggs and ham.','Available','https://i.imgur.com/KNPlQ73.jpeg'),(112,'Matilda',71,'978-0142410370',1988,'Children','A children\'s novel about a gifted girl with telekinetic powers.','Available','https://i.imgur.com/zFbYIr6.jpeg'),(113,'The Very Hungry Caterpillar',73,'978-0399226908',1969,'Children','A children\'s picture book about a caterpillar who eats his way through various foods.','Available','https://i.imgur.com/vgk0WSD.jpeg');
