INSERT INTO `review` VALUES (1,43,13,5,'I really enjoyed reading Dune. The story is immersive and full of interesting characters, and the unique world-building kept me engaged from beginning to end. I can even edit my review if I wish.','2026-05-31 10:35:51'),(3,43,16,5,'Dune was way more intense than I expected. I really liked Paul’s journey and couldn’t stop thinking about the story after I finished it.','2026-05-31 21:22:04'),(4,61,13,5,'This book was full of twists and kept me guessing the whole time. The unreliable narrators made the story even more interesting and surprising.','2026-05-31 21:53:09'),(5,33,13,5,'This book felt emotional and thoughtful, with characters who seemed very real. It was sad at times but beautifully written.','2026-05-31 21:53:28'),(6,87,12,5,'I enjoyed learning about Einstein\'s life beyond his scientific achievements. The book made complex ideas feel more understandable and showed how fascinating he was as a person.','2026-05-31 21:54:09'),(7,97,18,5,'This book gave a clear overview of one of the most important periods in modern history. It helped me understand the global impact of the Cold War without feeling overwhelming.','2026-05-31 21:54:58'),(8,33,18,5,'I liked how the story explored love, loss, and growing up. The atmosphere stayed with me long after I finished reading.','2026-05-31 21:55:15'),(9,94,18,5,'The book provided a detailed and engaging look at the French Revolution and its key figures. It made a complicated historical event feel vivid and dramatic.','2026-05-31 21:55:40'),(10,102,17,5,'The poems were beautiful and full of emotion. Even when I didn’t fully understand every line, I could feel the passion and sadness in the writing.','2026-05-31 21:56:18'),(12,35,13,5,'Best book ever!','2026-06-06 11:44:29');
/*!40000 ALTER TABLE `review` ENABLE KEYS */;
UNLOCK TABLES;

